steps.fragment:
// Objekti, svojstva, reference i mutacija
// Nezavisni primeri ovog koraka. Odeljak označen komentarom pokazuje kod koji ne treba pokretati kao deo fajla.

// Objekat
const korisnik = {
  ime: "Ana",
  godine: 22,
  aktivan: true
};

// Pristup tačkom
console.log(korisnik.ime); // "Ana"

// Pristup zagradama
console.log(korisnik["godine"]); // 22

// Ključ u promenljivoj
const polje = "ime";

console.log(korisnik[polje]); // "Ana"

// Izmena i delete
korisnik.aktivan = false;
korisnik.grad = "Niš";

const uklonjeno = delete korisnik.godine;

// Kopija primitivne vrednosti
let a = 10;
let b = a;

b = 20;

console.log(a); // 10
console.log(b); // 20

// Deljena referenca
const prvi = {
  ime: "Ana"
};

const drugi = prvi;

drugi.ime = "Marko";

console.log(prvi.ime); // "Marko"

// Mutacija svojstva
const osoba = {
  ime: "Ana"
};

osoba.ime = "Milica"; // Dozvoljeno

// Nova dodela const promenljivoj
// osoba = { ime: "Petar" }; // TypeError

