steps.fragment:
// Izrazi, operatori i poređenja
// Nezavisni primeri ovog koraka. Odeljak označen komentarom pokazuje kod koji ne treba pokretati kao deo fajla.

// Aritmetika
10 + 3;   // 13
10 - 3;   // 7
10 * 3;   // 30
10 / 3;   // 3.333...
10 % 3;   // 1
2 ** 3;   // 8

// Spajanje stringova
"Web" + " programiranje";
// "Web programiranje"

// Implicitna konverzija
10 + "5"; // "105"
10 - "5"; // 5

// Eksplicitna konverzija
Number("25"); // 25
String(25);   // "25"

// NaN
Number("tekst"); // NaN

// Stroga i labava jednakost
5 === 5;     // true
5 === "5";   // false

5 == "5";    // true
0 == false;  // true

// Identitet objekta
const a = { x: 1 };
const b = { x: 1 };
const c = a;

console.log(a === b); // false
console.log(a === c); // true

// NaN nije jednak sebi
NaN === NaN; // false

// Logički operatori
true && false; // false
true || false; // true
!true;         // false

// Vrednost operanda
"tekst" && 42; // 42
0 || 100;      // 100

// Prioritet
2 + 3 * 4;   // 14
(2 + 3) * 4; // 20

