  default:
    console.log("Nepoznata komanda");
}

const broj = 12;

const opis = broj % 2 === 0
  ? "paran"
  : "neparan";

for (let i = 0; i < 5; i++) {
  console.log(i);
}

let broj = 1;

while (broj < 100) {
  broj = broj * 2;
}

discussion.text:
5.1. Kako program odlučuje koji kod se izvršava?

```javascript
const broj = 0;

if (broj) {
  console.log("A");
} else {
  console.log("B");
}
```

Šta se ispisuje i zašto?

5.2. Da li `switch` automatski prekida izvršavanje posle pogođenog `case`?

```javascript
const x = 1;

switch (x) {
  case 1:
    console.log("A");
  case 2:
    console.log("B");
    break;
  default:
    console.log("C");
}
```

Šta se ispisuje?

5.3. Kako se razlikuju `for`, `while`, `break` i `continue`?

```javascript
for (let i = 0; i < 5; i++) {
  if (i === 2) continue;
  if (i === 4) break;

  console.log(i);
}
```

Koje vrednosti se ispisuju?

