// Funkcije kao vrednosti
// Nezavisni primeri ovog koraka. Odeljak označen komentarom pokazuje kod koji ne treba pokretati kao deo fajla.

// Deklaracija i poziv
function kvadrat(broj) {
  return broj * broj;
}

const rezultat = kvadrat(5);

console.log(rezultat); // 25

// Podrazumevani parametar
function pozdrav(ime = "goste") {
  return "Zdravo, " + ime;
}

pozdrav();      // "Zdravo, goste"
pozdrav("Ana"); // "Zdravo, Ana"

// Deklaracija funkcije
function saberi(a, b) {
  return a + b;
}

// Funkcijski izraz
const saberi = function(a, b) {
  return a + b;
};

// Arrow funkcija
const saberi = (a, b) => a + b;

// Funkcija je vrednost
function dupliraj(x) {
  return x * 2;
}

const operacija = dupliraj;

console.log(operacija(4)); // 8

// Callback
function primeni(vrednost, funkcija) {
  return funkcija(vrednost);
}

const rezultat = primeni(5, x => x * 3);

console.log(rezultat); // 15

// Funkcija višeg reda
function napraviMnozenje(faktor) {
  return (broj) => broj * faktor;
}

const utrostruci = napraviMnozenje(3);

console.log(utrostruci(5)); // 15

blocks.text:
const brojevi = [3, 6, 9];

for (const broj of brojevi) {
  console.log(broj);
}

const brojevi = [1, 2];

brojevi.push(3);

console.log(brojevi); // [1, 2, 3]

const brojevi = [1, 2, 3];

const kvadrati = brojevi.map(x => x * x);

console.log(kvadrati); // [1, 4, 9]
console.log(brojevi);  // [1, 2, 3]

const brojevi = [3, 8, 11, 16];

const parni = brojevi.filter(x => x % 2 === 0);

console.log(parni); // [8, 16]

const brojevi = [4, 7, 12, 15];

const rezultat = brojevi.find(x => x > 10);

console.log(rezultat); // 12

const brojevi = [2, 4, 6];

const zbir = brojevi.reduce(
  (akumulator, broj) => akumulator + broj,
  0
);

console.log(zbir); // 12

const imena = ["Ana", "Marko", "Sara"];

imena.forEach(ime => {
  console.log(ime);
});

discussion.text:
7.1. Šta je niz i kako se razlikuje od običnog objekta?

```javascript
const brojevi = [10, 20, 30];

brojevi.push(40);

console.log(brojevi[0]);
console.log(brojevi.length);
```

Šta se ispisuje i da li je operacija `push` dozvoljena ako je niz deklarisan sa `const`?

7.2. Zašto koristiti `map` ako već imamo `for` petlju?

```javascript
const brojevi = [1, 2, 3];

const rezultat = brojevi.map(x => x * 2);
```

Šta sadrži `rezultat` i da li se `brojevi` menja?

7.3. Ako tražimo elemente koji zadovoljavaju uslov, kada koristimo `filter`, a kada `find`?

```javascript
const brojevi = [4, 7, 12, 15];

const a = brojevi.filter(x => x > 10);
