// Execution context, call stack i hoisting
// Nezavisni primeri ovog koraka. Odeljak označen komentarom pokazuje kod koji ne treba pokretati kao deo fajla.
// Pri stvaranju konteksta JavaScript engine prvo upiše deklaracije, pa izvršava naredbe i dodele.

// Ugneždeni pozivi
function kvadrat(x) {
  return x * x;
}

function izracunaj(a) {
  const rezultat = kvadrat(a);
  return rezultat + 1;
}

