console.log(saberi(2, 3)); // 5

function saberi(a, b) {
  return a + b;
}

// var pre dodele
console.log(broj); // undefined

var broj = 10;

// Temporal Dead Zone
// console.log(broj); // ReferenceError
//
// let broj = 10;

// const i funkcijski izraz
// Prvi prolaz upiše ime. Funkcija nastaje tek u prolazu izvršenja.
