  return `Zdravo, ${this.ime}`;
};

const ana = new Korisnik("Ana");

class Korisnik {
  constructor(ime) {
    this.ime = ime;
  }

  pozdrav() {
    return `Zdravo, ${this.ime}`;
  }
}

const ana = new Korisnik("Ana");

console.log(ana.pozdrav());
// "Zdravo, Ana"

class Administrator extends Korisnik {
  constructor(ime, nivo) {
    super(ime);
    this.nivo = nivo;
  }
}

const admin = new Administrator("Ana", 2);

console.log(admin.pozdrav());
// "Zdravo, Ana"

