steps.fragment:
// Prototipi, prototipski lanac i klase
// Nezavisni primeri ovog koraka. Odeljak označen komentarom pokazuje kod koji ne treba pokretati kao deo fajla.

// Object.create
const zajednicko = {
  pozdrav() {
    return `Zdravo, ${this.ime}`;
  }
};

const korisnik = Object.create(zajednicko);

korisnik.ime = "Ana";

console.log(korisnik.pozdrav());
// "Zdravo, Ana"

// getPrototypeOf
Object.getPrototypeOf(korisnik) === zajednicko;
// true

// hasOwn
Object.hasOwn(korisnik, "ime");     // true
Object.hasOwn(korisnik, "pozdrav"); // false

// Konstruktor
function Korisnik(ime) {
  this.ime = ime;
}

Korisnik.prototype.pozdrav = function() {
  return `Zdravo, ${this.ime}`;
};

const ana = new Korisnik("Ana");

// class
class Korisnik {
  constructor(ime) {
    this.ime = ime;
  }

  pozdrav() {
    return `Zdravo, ${this.ime}`;
  }
}

const ana = new Korisnik("Ana");

console.log(ana.pozdrav());
// "Zdravo, Ana"

// Prototip instance
Object.getPrototypeOf(ana) === Korisnik.prototype;
// true

// extends
class Administrator extends Korisnik {
  constructor(ime, nivo) {
    super(ime);
    this.nivo = nivo;
  }
}

const admin = new Administrator("Ana", 2);

console.log(admin.pozdrav());
// "Zdravo, Ana"

