// Formulari, unos i podrazumevane radnje
// Nezavisni primeri ovog koraka. Odeljak označen komentarom pokazuje kod koji ne treba pokretati kao deo fajla.

// Kontrolna soba
// Dodati formu za zadavanje ciljne temperature, sa `min`, `max`, `required` i smislenom oznakom (`label`). Na `submit` sprečiti navigaciju, pročitati podatak i proveriti dozvoljeni opseg. Privremeno prikazati zadatu temperaturu. Dugmad unutar forme koja ne služe za slanje dobijaju `type="button"`.
//
// Provera: Enter i klik na „Sačuvaj” imaju isti efekat; neispravan unos ne prolazi; stranica se ne osvežava.
//
// ---
// # III. Stanje i prikaz: od podataka do interfejsa

// HTML
/*
<form id="konverzija">
  <label for="stepeni">Temperatura u °C</label>
  <input id="stepeni" name="stepeni" type="number" required>
  <button type="submit">Pretvori</button>
</form>
<p id="rezultat"></p>
*/

// forma
const forma = document.querySelector("#konverzija");
const rezultat = document.querySelector("#rezultat");

forma.addEventListener("submit", (event) => {
  event.preventDefault();
  const podaci = new FormData(forma);
  const tekst = podaci.get("stepeni");
  if (typeof tekst !== "string" || tekst.trim() === "") return;

  const c = Number(tekst);
  if (!Number.isFinite(c)) return;
  rezultat.textContent = `${(c * 9 / 5 + 32).toFixed(1)} °F`;
});

