const podrazumevano = { tema: "svetla", font: 16 };

function sacuvaj(podesavanja) {
  localStorage.setItem("podesavanja", JSON.stringify(podesavanja));
}

function ucitaj() {
  try {
    const tekst = localStorage.getItem("podesavanja");
    if (tekst === null) return { ...podrazumevano };

    const podaci = JSON.parse(tekst);
    if (!podaci || typeof podaci !== "object") {
      return { ...podrazumevano };
    }
    return {
      tema: podaci.tema === "tamna" ? "tamna" : "svetla",
      font: Number.isFinite(podaci.font) && podaci.font >= 12 && podaci.font <= 24
        ? podaci.font : 16
    };
  } catch {
    return { ...podrazumevano };
  }
}

