app.get('/uredjaji/:id', (req, res) => {
  if (!/^[1-9]\d*$/.test(req.params.id)) {
    return res.status(400).json({ greska: 'ID mora biti pozitivan ceo broj' });
  }
  const id = Number(req.params.id);
  if (!Number.isSafeInteger(id)) {
    return res.status(400).json({ greska: 'ID je van dozvoljenog opsega' });
  }

  const uredjaj = uredjaji.find(x => x.id === id);
  if (!uredjaj) {
    return res.status(404).json({ greska: 'Uređaj ne postoji' });
  }
  res.json(uredjaj);
});

